/**
 * scripts/open-loop-ledger-dispositions-149j.ts — wave 149, lane 149J: the 575 rows the wave-148 ledger left `unverified`.
 *
 * Owner ruling 20 (2026-11-03): "Finish every open loop and every 'not done' note from the parallel agents." Every row
 * below was re-read against the tree at 08712fef (+ this lane's patch) — `$S/149J-q*.txt` hold the greps. A `closed`
 * row names evidence the generator re-derives on every run (stripped-source anchors, `raw:` for a comment fix,
 * `chain:` / `key:` / `mig:`), so a closure that stops being true turns test:open-loop-ledger red. A `carried` row says
 * WHY in words (never the [UNVERIFIED] default) and hands it to the wave-149 lane whose file domain holds it
 * (WAVE149_SPEC.md "LANES"; lane149Z = no wave-149 lane owns the file — the convergence lane), the owner, counsel or the
 * integrator. Merged into MANUAL_DISPOSITIONS by scripts/open-loop-ledger-dispositions.ts (one map — the guard's D check
 * holds every key to an inventory id).
 */
import type { Disposition } from "./open-loop-ledger"

const J = "wave 149 lane 149J re-evaluation at 08712fef"
type O = NonNullable<Disposition["o"]>
type K = NonNullable<Disposition["k"]>
const cl = (e: string[], note = "", lc?: boolean): Disposition => ({ s: "closed", e, by: note ? `${J} — ${note}` : J, ...(lc === undefined ? {} : { lc }) })
const ca = (k: K, o: O, r: string, lc?: boolean, e?: string[]): Disposition => ({ s: "carried", k, o, r, ...(lc === undefined ? {} : { lc }), ...(e ? { e } : {}) })

